// Offline build of the weapon customization (attachment) data from local snapshots only.
//   db/source/wiki_attachments.json  <- scripts/fetch-attachments.mjs (Module:Weapon Attach cost data + Cargo rows)
//   db/source/wiki_pages.json        <- weapon pages, to check which ones carry {{Attachments Table}}
//   dist/data/personal-weapons.js    <- primary weapon ids (generated by scripts/build-weapons.mjs)
//   db/source/namu_attachments.json  <- Korean attachment names, scripts/fetch-namu-attachments.mjs
// Writes dist/data/weapon-attachments.js. Usage: node scripts/build-attachments.mjs [--stdout]
//
// It does what Module:Weapon Attach does for each weapon page: every Cargo row whose
// "available on" list holds the weapon gives the slot and stat changes, and the cost data
// gives the unlock level and cost. Values the wiki does not give stay null (shown as unconfirmed).
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { personalWeapons } from '../dist/data/personal-weapons.js';

const root = new URL('../', import.meta.url);
// In-game order of the customization slots (Namu Wiki: optics, underbarrel, muzzle, magazine).
export const SLOTS = { Optics: 'optics', Underbarrel: 'underbarrel', Muzzle: 'muzzle', Magazine: 'magazine' };
// Weapon names misspelled in an attachment page's "available on" list. A fix is used only
// when the cost data lists that attachment for the corrected weapon.
const NAME_FIXES = { 'SG-SG-225IE Breaker Incendiary': 'SG-225IE Breaker Incendiary' };

const SEP = /\s*&nbsp;&bull;&nbsp;\s*/;
const fail = (where, field, value) => { throw new Error(`${where}: unexpected ${field} ${JSON.stringify(value)}`); };
const number = (where, field, value, pattern = /^\d+(\.\d+)?$/) => pattern.test(value) ? Number(value) : fail(where, field, value);
// Cargo text -> site values. Relative changes keep the wiki's sign and % ("+25%", "-5");
// "= 75" means the attachment sets the value outright.
const PARSE = {
  ergonomics: (v, w) => number(w, 'ergonomics', v, /^[+-]?\d+$/),
  sway: (v, w) => /^[+-]\d+%$/.test(v) ? v : fail(w, 'sway', v),
  horizontal_recoil: (v, w) => /^[+-]\d+%$/.test(v) ? v : fail(w, 'horizontal_recoil', v),
  vertical_recoil: (v, w) => /^[+-]\d+%$/.test(v) ? v : fail(w, 'vertical_recoil', v),
  horizontal_spread: (v, w) => /^([+-]\d+%|= \d+)$/.test(v) ? v : fail(w, 'horizontal_spread', v),
  vertical_spread: (v, w) => /^([+-]\d+%|= \d+)$/.test(v) ? v : fail(w, 'vertical_spread', v),
  fire_rate: (v, w) => number(w, 'fire_rate', v),
  optic_range: (v, w) => v.split(SEP).map(part => number(w, 'optic_range', part.replace(/m$/, ''))),
  mag_capacity: (v, w) => number(w, 'mag_capacity', v),
  max_magazines: (v, w) => number(w, 'max_magazines', v),
  start_magazines: (v, w) => number(w, 'start_magazines', v),
  heatsink_overheat: (v, w) => number(w, 'heatsink_overheat', v),
  heatsink_cooldown: (v, w) => number(w, 'heatsink_cooldown', v),
  heatsink_temp_per_shot: (v, w) => number(w, 'heatsink_temp_per_shot', v),
  full_reload_time: (v, w) => number(w, 'full_reload_time', v.replace(/s$/, '')),
  partial_reload_time: (v, w) => number(w, 'partial_reload_time', v.replace(/s$/, '')),
  functionality: (v, w) => v.split(SEP).map(part => ({ Laser: 'laser', Flashlight: 'flashlight' })[part] ?? fail(w, 'functionality', part)),
};
// Site names of the effect keys, in the order the wiki lists them.
const EFFECT_KEYS = {
  ergonomics: 'ergonomics', optic_range: 'zoom', sway: 'sway', fire_rate: 'fireRate',
  vertical_recoil: 'verticalRecoil', horizontal_recoil: 'horizontalRecoil',
  vertical_spread: 'verticalSpread', horizontal_spread: 'horizontalSpread',
  mag_capacity: 'magCapacity', heatsink_overheat: 'overheat', heatsink_cooldown: 'cooldown',
  heatsink_temp_per_shot: 'heatPerShot', start_magazines: 'startMags', max_magazines: 'maxMags',
  full_reload_time: 'reload', partial_reload_time: 'reloadTactical', functionality: 'function',
};
const slug = text => text.toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9.]+/g, '-').replace(/\./g, '-').replace(/^-|-$/g, '');
// "3,000" -> 3000; "BUILT-IN" -> fixed part; anything else ("ENTER COST", missing) -> unconfirmed.
function unlockOf(entry) {
  if (!entry) return { level: null, cost: null };
  const level = Number.isInteger(entry.lvl) ? entry.lvl : /^\d+$/.test(String(entry.lvl ?? '')) ? Number(entry.lvl) : null;
  const raw = String(entry.cost ?? '');
  if (raw === 'BUILT-IN') return { level, cost: null, builtIn: true };
  return { level, cost: /^\d{1,3}(,\d{3})*$/.test(raw) ? Number(raw.replaceAll(',', '')) : null };
}

// Korean names from Namu Wiki's weapon tables, which give no English names. A site row and a Namu
// row of the same weapon (code and Korean name) are the same attachment when they have the same slot
// and unlock ('기본' = the level 1 free or built-in default; otherwise the same level and cost) and
// neither has another candidate. Namu's empty choices ('없음') and the site's `none` parts are left
// out. An English name gets a Korean name only when every such match agrees on it and no other
// English name gets the same one; the rest stay in English (returned as gaps).
// English names the user chose to name by the Namu majority (2026-11-09): Reflex Sight Mk2 matches
// '반사식 조준경 MK2' on 27 weapons and '홀로그램 조준경' only on the Liberator Concussive's row.
export const MAJORITY_ACCEPTED = ['Reflex Sight Mk2'];
// Korean names the user gave for attachments Namu could not tie to a row (2026-11-09).
export const USER_NAMED = { 'High Capacity Heatsink': '고용량 방열판', 'Laser Sight': '레이저 조준경' };
const isDefault = item => item.level === 1 && (item.cost === 0 || item.builtIn === true);
const fitsNamu = (row, item) => row.default ? isDefault(item) : row.level === item.level && row.cost != null && row.cost === item.cost;
export function namuMatches(namu, parts, list, weapon) {
  const table = namu.weapons.find(entry => entry.code === weapon.code && entry.name === weapon.name);
  if (!table) return [];
  const rows = table.rows.filter(row => !/없음/.test(row.name));
  const items = list.filter(item => !parts[item.part].none);
  const matches = [];
  for (const item of items) {
    const slot = parts[item.part].slot;
    const fits = rows.filter(row => row.slot === slot && fitsNamu(row, item));
    if (fits.length !== 1) continue;
    if (items.filter(other => parts[other.part].slot === slot && fitsNamu(fits[0], other)).length !== 1) continue;
    matches.push({ item, row: fits[0] });
  }
  return matches;
}
function koreanNames(namu, parts, out, weapons) {
  const votes = new Map(); // English name -> Map(Korean name -> [weapon id])
  for (const weapon of weapons) {
    if (!out[weapon.id]) continue;
    for (const { item, row } of namuMatches(namu, parts, out[weapon.id], weapon)) {
      const en = parts[item.part].name, ko = row.name.replace(/\s+/g, ' ').trim();
      if (!votes.has(en)) votes.set(en, new Map());
      votes.get(en).set(ko, [...(votes.get(en).get(ko) ?? []), weapon.id]);
    }
  }
  const names = new Map(), gaps = [];
  for (const [en, kos] of votes) {
    const ranked = [...kos].sort((a, b) => b[1].length - a[1].length);
    if (kos.size === 1) names.set(en, ranked[0][0]);
    else if (MAJORITY_ACCEPTED.includes(en) && ranked[0][1].length > ranked[1][1].length) names.set(en, ranked[0][0]);
    else gaps.push({ name: en, issue: `Namu rows disagree: ${[...kos].map(([ko, ids]) => `${ko} (${ids.join(', ')})`).join(' / ')}` });
  }
  for (const [en, ko] of Object.entries(USER_NAMED)) names.set(en, ko);
  for (const [en, ko] of names) {
    const shared = [...names].filter(([, other]) => other === ko).map(([name]) => name);
    if (shared.length > 1) gaps.push({ name: en, issue: `Korean name "${ko}" also matched ${shared.filter(name => name !== en).join(', ')}` });
  }
  for (const gap of gaps) names.delete(gap.name);
  for (const en of new Set(Object.values(parts).filter(part => !part.none).map(part => part.name))) if (!votes.has(en) && !USER_NAMED[en]) gaps.push({ name: en, issue: 'no single Namu row matches by slot, level and cost' });
  return { names, gaps: gaps.sort((a, b) => a.name < b.name ? -1 : 1) };
}

// Primary weapons only: on the wiki, secondaries and support weapons have at most a fixed built-in part.
export const PRIMARIES = personalWeapons.filter(w => w.category === 'primary');
export function buildAttachments(snapshot, weaponPages, namu = null, weapons = PRIMARIES) {
  const discrepancies = [];
  const costs = snapshot.costs.data;

  // Shared attachment definitions: one per Cargo row (a page with variants has several rows).
  const parts = {};
  const fits = new Map(); // weapon title -> [part id]
  const pageRows = new Map();
  for (const row of snapshot.cargo.rows) {
    const slot = SLOTS[row.type] ?? fail(row._pageName, 'type', row.type);
    const index = (pageRows.get(row._pageName) ?? 0) + 1;
    pageRows.set(row._pageName, index);
    const where = `${row._pageName} (row ${index})`;
    const effects = {};
    for (const [field, key] of Object.entries(EFFECT_KEYS)) if (row[field]) effects[key] = PARSE[field](row[field], where);
    const page = snapshot.pages[row._pageName] ?? fail(where, 'page (not in pages)', row._pageName);
    const id = slug(row._pageName) + (index > 1 ? `-${index}` : '');
    parts[id] = { slot, name: row._pageName, ...(/^No /.test(row._pageName) ? { none: true } : {}), effects, source: page.source, revision: page.revision };
    for (const raw of row.available_on.split(',').map(name => name.trim()).filter(Boolean)) {
      let title = raw;
      if (NAME_FIXES[raw]) {
        title = NAME_FIXES[raw];
        if (!costs[title.toUpperCase()]?.[row._pageName.toUpperCase()]) throw new Error(`${where}: name fix "${raw}" -> "${title}" has no cost entry`);
        discrepancies.push({ weapon: title, attachment: row._pageName, issue: `listed as "${raw}" on the attachment page, so the wiki's own table leaves it out; read as "${title}"`, source: page.source, revision: page.revision });
      }
      if (!fits.has(title)) fits.set(title, []);
      fits.get(title).push(id);
    }
  }

  // Weapons with data that are not primaries on the gear page are listed as skipped.
  const out = {};
  const known = new Set(weapons.map(w => w.en.toUpperCase()));
  const skipped = [...new Set([...fits.keys(), ...Object.keys(costs)].map(title => title.toUpperCase()))].filter(title => !known.has(title)).sort();
  const order = Object.values(SLOTS);
  for (const weapon of weapons) {
    if (!fits.has(weapon.en) && !costs[weapon.en.toUpperCase()]) continue;
    const entry = costs[weapon.en.toUpperCase()] ?? {};
    const ids = fits.get(weapon.en) ?? [];
    const names = new Set(ids.map(id => parts[id].name.toUpperCase()));
    const list = ids.map(id => {
      const unlock = unlockOf(entry[parts[id].name.toUpperCase()]);
      if (unlock.level == null || (unlock.cost == null && !unlock.builtIn)) discrepancies.push({ weapon: weapon.en, attachment: parts[id].name, issue: `no unlock level/cost in ${snapshot.costs.title} (${JSON.stringify(entry[parts[id].name.toUpperCase()] ?? null)})`, source: snapshot.costs.source, revision: snapshot.costs.revision });
      return { part: id, ...unlock };
    });
    for (const name of Object.keys(entry).filter(name => !names.has(name))) {
      // Priced but no Cargo row for this weapon: the slot is known from the page, the stat changes are not.
      const page = snapshot.cargo.rows.find(row => row._pageName.toUpperCase() === name);
      if (!page) throw new Error(`${weapon.en}: "${name}" in ${snapshot.costs.title} is not an attachment page`);
      const id = `${slug(page._pageName)}-${weapon.id}`;
      parts[id] = { slot: SLOTS[page.type], name: page._pageName, ...(/^No /.test(page._pageName) ? { none: true } : {}), effects: null, source: snapshot.pages[page._pageName].source, revision: snapshot.pages[page._pageName].revision };
      list.push({ part: id, ...unlockOf(entry[name]) });
      discrepancies.push({ weapon: weapon.en, attachment: page._pageName, issue: `priced in ${snapshot.costs.title} but the attachment page does not list the weapon; stat changes unconfirmed`, source: parts[id].source, revision: parts[id].revision });
    }
    // Wiki order: slot, then unlock level, then name.
    list.sort((a, b) => order.indexOf(parts[a.part].slot) - order.indexOf(parts[b.part].slot) || (a.level ?? 0) - (b.level ?? 0) || (parts[a.part].name.toUpperCase() < parts[b.part].name.toUpperCase() ? -1 : 1));
    out[weapon.id] = list;
  }

  // Every gear weapon whose wiki page has the attachments table has data, and the other way round.
  for (const weapon of weapons) {
    const wikitext = weaponPages.pages[weapon.en]?.wikitext ?? '';
    const onPage = /\{\{\s*Attachments Table\s*\|/.test(wikitext);
    if (onPage !== Boolean(out[weapon.id])) throw new Error(`${weapon.en}: the wiki page ${onPage ? 'has' : 'has no'} {{Attachments Table}} but the attachment data ${out[weapon.id] ? 'lists' : 'does not list'} it`);
  }
  const used = new Set(Object.values(out).flat().map(item => item.part));
  for (const id of Object.keys(parts)) if (!used.has(id)) delete parts[id];
  // Korean names (ko) go right after the English name.
  const korean = namu ? koreanNames(namu, parts, out, weapons) : { names: new Map(), gaps: [] };
  for (const [id, { slot, name, ...rest }] of Object.entries(parts)) parts[id] = { slot, name, ...(korean.names.has(name) ? { ko: korean.names.get(name) } : {}), ...rest };

  return {
    source: {
      source: snapshot.source, license: snapshot.license, retrievedAt: snapshot.retrievedAt,
      costs: snapshot.costs.source, costsRevision: snapshot.costs.revision, costsRevisionTimestamp: snapshot.costs.revisionTimestamp,
      cargo: snapshot.cargo.source, cargoRows: snapshot.cargo.rows.length, attachmentPages: Object.keys(snapshot.pages).length,
      code: Object.fromEntries(Object.entries(snapshot.code).map(([title, page]) => [title, page.revision])),
      ...(namu ? { koreanNames: namu.source, koreanNamesModifiedAt: namu.modifiedAt, koreanNamesRetrievedAt: namu.retrievedAt } : {}),
      skipped,
    },
    parts,
    weapons: out,
    discrepancies,
    koreanGaps: korean.gaps,
  };
}

// JSON with one line per record.
const lines = (object, indent = '  ') => `{\n${Object.entries(object).map(([key, value]) => `${indent}${JSON.stringify(key)}: ${value}`).join(',\n')}\n}`;
export function formatModule(built) {
  return `// Generated by scripts/build-attachments.mjs from local db/source/wiki_attachments.json. Do not edit by hand.
export const weaponAttachmentsCheckedAt = ${JSON.stringify(built.source.retrievedAt)};

export const weaponAttachmentsSource = ${JSON.stringify(built.source)};

// Attachment definitions (one per wiki attachment row; a page with variants has several).
// ko: Korean name from Namu Wiki (missing = shown in English). none: the empty choice (no attachment).
// effects: null when the wiki gives no stat changes for that weapon.
export const attachmentParts = ${lines(Object.fromEntries(Object.entries(built.parts).map(([id, part]) => [id, JSON.stringify(part)])))};

// Weapon id -> attachments in slot / unlock level order. level, cost: null = unconfirmed;
// builtIn: true for a fixed part that comes with the weapon (no cost).
export const weaponAttachments = ${lines(Object.fromEntries(Object.entries(built.weapons).map(([id, list]) => [id, `[\n${list.map(item => `    ${JSON.stringify(item)}`).join(',\n')}\n  ]`])))};

export const attachmentDiscrepancies = [
${built.discrepancies.map(item => `  ${JSON.stringify(item)}`).join(',\n')}
];
`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const read = async path => JSON.parse(await readFile(new URL(path, root), 'utf8'));
  const built = buildAttachments(await read('db/source/wiki_attachments.json'), await read('db/source/wiki_pages.json'), await read('db/source/namu_attachments.json'));
  const text = formatModule(built);
  if (process.argv.includes('--stdout')) process.stdout.write(text);
  else {
    await writeFile(new URL('dist/data/weapon-attachments.js', root), text);
    const total = Object.values(built.weapons).reduce((sum, list) => sum + list.length, 0);
    const named = new Set(Object.values(built.parts).filter(part => part.ko).map(part => part.name));
    console.log(`Wrote dist/data/weapon-attachments.js (${Buffer.byteLength(text)} bytes): ${Object.keys(built.weapons).length} weapons, ${total} attachment rows, ${Object.keys(built.parts).length} parts, ${built.discrepancies.length} discrepancies; skipped (not a primary on the gear page): ${built.source.skipped.join(', ') || 'none'}.`);
    console.log(`Korean names: ${named.size} attachment names; left in English: ${built.koreanGaps.length}${built.koreanGaps.map(gap => `\n  ${gap.name}: ${gap.issue}`).join('')}`);
  }
}
